        #pragma clang diagnostic ignored "-Wmissing-prototypes"
        #pragma clang diagnostic ignored "-Wmissing-braces"

        #include <metal_stdlib>
        #include <simd/simd.h>

        using namespace metal;

        template<typename T, size_t Num>
        struct spvUnsafeArray
        {
            T elements[Num ? Num : 1];

            thread T& operator [] (size_t pos) thread
            {
                return elements[pos];
            }
            constexpr const thread T& operator [] (size_t pos) const thread
            {
                return elements[pos];
            }

            device T& operator [] (size_t pos) device
            {
                return elements[pos];
            }
            constexpr const device T& operator [] (size_t pos) const device
            {
                return elements[pos];
            }

            constexpr const constant T& operator [] (size_t pos) const constant
            {
                return elements[pos];
            }

            threadgroup T& operator [] (size_t pos) threadgroup
            {
                return elements[pos];
            }
            constexpr const threadgroup T& operator [] (size_t pos) const threadgroup
            {
                return elements[pos];
            }
        };

        // Returns the determinant of a 2x2 matrix.
        static inline __attribute__((always_inline))
        float spvDet2x2(float a1, float a2, float b1, float b2)
        {
            return a1 * b2 - b1 * a2;
        }

        // Returns the inverse of a matrix, by using the algorithm of calculating the classical
        // adjoint and dividing by the determinant. The contents of the matrix are changed.
        static inline __attribute__((always_inline))
        float3x3 spvInverse3x3(float3x3 m)
        {
            float3x3 adj; // The adjoint matrix (inverse after dividing by determinant)

            // Create the transpose of the cofactors, as the classical adjoint of the matrix.
            adj[0][0] =  spvDet2x2(m[1][1], m[1][2], m[2][1], m[2][2]);
            adj[0][1] = -spvDet2x2(m[0][1], m[0][2], m[2][1], m[2][2]);
            adj[0][2] =  spvDet2x2(m[0][1], m[0][2], m[1][1], m[1][2]);

            adj[1][0] = -spvDet2x2(m[1][0], m[1][2], m[2][0], m[2][2]);
            adj[1][1] =  spvDet2x2(m[0][0], m[0][2], m[2][0], m[2][2]);
            adj[1][2] = -spvDet2x2(m[0][0], m[0][2], m[1][0], m[1][2]);

            adj[2][0] =  spvDet2x2(m[1][0], m[1][1], m[2][0], m[2][1]);
            adj[2][1] = -spvDet2x2(m[0][0], m[0][1], m[2][0], m[2][1]);
            adj[2][2] =  spvDet2x2(m[0][0], m[0][1], m[1][0], m[1][1]);

            // Calculate the determinant as a combination of the cofactors of the first row.
            float det = (adj[0][0] * m[0][0]) + (adj[0][1] * m[1][0]) + (adj[0][2] * m[2][0]);

            // Divide the classical adjoint matrix by the determinant.
            // If determinant is zero, matrix is not invertable, so leave it unchanged.
            return (det != 0.0f) ? (adj * (1.0f / det)) : m;
        }

        struct pbr_vs_params
        {
            float4x4 view_proj;
            packed_float3 eye_pos;
            float _pad0;
            float4 u_morphWeights[2];
            int use_uniform_skinning;
            int _pad1;
            int _pad2;
            int _pad3;
            float4 csm_normal_offsets;
            float4x4 finalBonesMatrices[128];
            float4x4 csm_vp[1];
        };

        struct main0_out
        {
            float3 v_Position [[user(locn0)]];
            float3 v_Normal [[user(locn1)]];
            float4 v_Tangent [[user(locn2)]];
            float2 v_TexCoord0 [[user(locn3)]];
            float2 v_TexCoord1 [[user(locn4)]];
            float4 v_Color [[user(locn5)]];
            float3 v_TBN_0 [[user(locn6)]];
            float3 v_TBN_1 [[user(locn7)]];
            float3 v_TBN_2 [[user(locn8)]];
            float4 v_Custom [[user(locn9)]];
            float4 v_ShadowPos_0 [[user(locn10)]];
            float4 gl_Position [[position]];
        };

        struct main0_in
        {
            float3 position [[attribute(0)]];
            float3 normal [[attribute(1)]];
            float2 texcoord_0 [[attribute(2)]];
            float4 tangent [[attribute(3)]];
            float4 in_model_0 [[attribute(4)]];
            float4 in_model_1 [[attribute(5)]];
            float4 in_model_2 [[attribute(6)]];
            float4 in_model_3 [[attribute(7)]];
            float4 in_custom [[attribute(8)]];
            float2 texcoord_1 [[attribute(9)]];
            float4 joints_0 [[attribute(10)]];
            float4 weights_0 [[attribute(11)]];
